  sectionOf(diagnosticBook).attempts.push(attempt("diagnostic", "diagnostic", "review"));
  sectionOf(diagnosticBook).objectiveChecks[0].checks = [...all];
  sectionOf(diagnosticBook).requiredChecks = [...all];
