```ts
export type UnitReviewRoleStatus = { role: ReviewRole; receipt?: ReviewReceipt };

export function unitReviewRoles(value: unknown, context: { contentHash: string; sourceHash: string; roles: readonly ReviewRole[] }): UnitReviewRoleStatus[] {
  const receipts = Array.isArray(value) ? value.filter(isReviewReceipt) : [];
  return context.roles.map(role => {
    const candidates = receipts.filter(r => r.role === role && r.contentHash === context.contentHash && r.sourceHash === context.sourceHash)
      .sort((a, b) => b.createdAt.localeCompare(a.createdAt));
    return { role, receipt: candidates[0] };
  });
}

export function unitBlockingFindings(value: unknown, context: {...& { responses?: readonly {key:string}[] }}): UnresolvedFinding[] {
  const responses = new Set((context.responses || []).map(r => r.key));
  return unitReviewRoles(value, context).flatMap(({role, receipt}) => !receipt || receipt.status !== "changes" ? []
    : receipt.findings.filter(f => f.severity === "blocking").map(finding => ({ role, key: computeFindingKey(role, finding), finding }))
      .filter(item => !responses.has(item.key)));
}

export function unitReviewFailures(value: unknown, context): ReviewFailure[] {
  return unitReviewRoles(value, context).flatMap(({receipt}) => receipt?.failure ? [receipt.failure] : []);
}
```

