const SOURCE_WINDOW_PAGES = 4;

/** One saved revision is one audit unit: bounded source windows over its cited pages, one
 * explanation check, and a visual check over its own embedded crops. No packet renders a page. */
export function planLessonUnitPackets(unit: LessonReviewUnit, section: ScholarSection, sourceHash: string, contextWindow?: number): ReviewPacket[] {
  const smallWindow = typeof contextWindow === "number" && contextWindow > 0 && contextWindow < 64_000;
  const windowPages = smallWindow ? 2 : SOURCE_WINDOW_PAGES;
  const bound = (values: number[]) => [...new Set(values.filter(page => Number.isSafeInteger(page) && page >= section.startPage && page <= section.endPage))].sort((a, b) => a - b);
  const checklist = (section.learnQuality?.coverage || []).filter(item => item.lessonId && matchesLessonId(unit.entryId, item.lessonId));
  const cited = bound([...unit.sourcePages, ...checklist.flatMap(item => item.sourcePages)]);
  // A unit that cites nothing inside the current section still gets its explanation checked;
  // source evidence then falls back to the section's own pages.
  const pages = cited.length ? cited : bound(Array.from({ length: section.endPage - section.startPage + 1 }, (_, index) => section.startPage + index));
  const crops = currentReviewSnapshots(section, sourceHash).filter(crop => unit.snapshotIds.includes(crop.id));
  const lesson = { id: unit.entryId, title: unit.title, markdown: unit.markdown };
  const base = { source: { startPage: section.startPage, endPage: section.endPage }, objectives: section.objectives, outline: [unit.title] };
  const packets: ReviewPacket[] = [];
  for (let index = 0; index < pages.length; index += windowPages) {
    const window = pages.slice(index, index + windowPages);
    packets.push({
      role: "source",
      id: `${unit.key}:source:${window[0]}`,
      instruction: `Unit check for saved explanation ${unit.entryId} (pages ${window.join(", ")}). Compare the saved explanation below against these pages and report essential content on them that it omits or misstates. Other units and the section-wide coverage plan are checked by their own audits.`,
      reads: window, views: [], cropIds: [],
      payload: { ...base, lesson, checklist: checklist.filter(item => item.sourcePages.some(page => window.includes(page))) },
    });
  }
  packets.push({
    role: "teaching",
    id: `${unit.key}:teaching`,
    instruction: `Unit check for saved explanation ${unit.entryId}. Judge this explanation as instruction for its declared pages; the section-wide recap, objective plan and other units are checked by their own audits.`,
    reads: pages, views: [], cropIds: [],
    payload: { ...base, lesson, checklist, checks: section.objectiveChecks, recap: section.synthesis, keyPoints: section.keyPoints },
  });
  if (crops.length) packets.push({
    role: "visual",
    id: `${unit.key}:visual`,
    instruction: `Unit check for saved explanation ${unit.entryId}. Inspect only the saved crops it embeds (pages ${[...new Set(crops.map(c => c.page))].join(", ")}); judge them against this unit's captions and equation callouts and the source inventory below. A saved crop must show its complete source figure with its labels, arrows and units.`,
    reads: [], views: [], cropIds: crops.map(crop => crop.id),
    payload: { ...base, lesson, figures: crops, figureInventory: (section.figureCoverage?.pages || []).filter(page => crops.some(crop => crop.page === page.page)), keyEquations: unit.markdown.match(/^> \[!note\][+-]? Key equation[^\n]*(?:\n>[^\n]*)*/gm) || [] },
  });
  return packets;
}
