  /** Persist finished unit checks while its audit continues, so an interruption keeps them. */
  const saveReviewCheckpoints = (draft: ScholarBook, store: (state: ScholarBook) => { reviews: ReviewReceipt[] } | undefined, contentHash: string, activation: ScholarRuntimeState, ctx: ExtensionContext) => {
    const latest = new Map<ReviewRole, ReviewBatchPass[]>();
    let chain = Promise.resolve(), scheduled = false, closed = false;
    const write = () => mutateBook(draft.id, state => {
      if (closed || activation !== session.state || !ports.isActiveAuthority(state) || state.source.fingerprint.sha256 !== draft.source.fingerprint.sha256) return;
      const quality = store(state);
      if (!quality) return;
      const checkpoints = [...latest].map(([role, batches]) => reviewCheckpoint(contentHash, draft.source.fingerprint.sha256, ctx, role, batches));
      quality.reviews = pruneReviewReceipts([...quality.reviews, ...checkpoints], { sourceHash: draft.source.fingerprint.sha256, model: reviewerModelName(ctx) });
    }).then(() => undefined, () => undefined);
    return {
      save: (role: ReviewPacketRole, batches: ReviewBatchPass[]) => {
        if (closed) return;
        latest.set(role, batches);
        if (!scheduled) { scheduled = true; chain = chain.then(() => { scheduled = false; return write(); }); }
      },
      close: async () => { await chain; closed = true; },
    };
  };
