  const startUnitAudit = (state: PreparationAuditor, draft: ScholarBook, target: ScholarSection | TutorSession, unit: LessonReviewUnit, sourceHash: string, ctx: ExtensionContext): UnitAudit => {
    const stop = new AbortController();
    const signal = ctx.signal ? AbortSignal.any([stop.signal, ctx.signal]) : stop.signal;
    reviewStops.add(stop);
