const reviewStore = (target: ScholarSection | TutorSession): ReviewReceiptStore => (state: ScholarBook) => {
  if ("objectives" in target) return findSection(state, target.id)?.learnQuality;
  const tutor = state.tutorSessions.find(item => item.id === target.id);
  if (!tutor) return undefined;
  tutor.review ||= { version: 1, receipts: [], responses: [] };
  return tutor.review;
};
