    { ...at(9), contentHash: "e".repeat(64), failure: { code: "cancelled", message: REVIEW_CHECKPOINT_MESSAGE } },   // live checkpoint
    at(3, { contentHash: "c".repeat(64) }),                                   // stale content still needed by the gate
